ext_view\\text_view.test.tsx:714:    it('pins the formatting toolbar above the document on desktop', () => {\napp\\src\\components\\text_view\\text_view.test.tsx:719:        expect(document.querySelector('[data-sticky-toolbar=\"true\"]')).not.toBeNull()\napp\\src\\components\\text_view\\text_view.test.tsx:722:    it('opens the standard action popup without an anchor from the editor toolbar', () => {\napp\\src\\components\\text_view\\text_view.test.tsx:727:        const editorToolbar = within(screen.getAllByTestId('mdx-editor-toolbar')[1])\napp\\src\\components\\text_view\\text_view.test.tsx:746:    it('opens Properties from the toolbar for a card with frontmatter', () => {\napp\\src\\components\\text_view\\text_view.test.tsx:753:        fireEvent.click(within(screen.getAllByTestId('mdx-editor-toolbar')[1]).getByRole('button', { name: 'Properties' }))\napp\\src\\components\\text_view\\text_view.test.tsx:772:        fireEvent.click(within(screen.getAllByTestId('mdx-editor-toolbar')[1]).getByRole('button', { name: 'Properties' }))\napp\\src\\components\\text_view\\text_view.test.tsx:786:    it('renders no Properties toolbar button for files without frontmatter', () => {\napp\\src\\components\\text_view\\text_view.test.tsx:791:        expect(within(screen.getAllByTestId('mdx-editor-toolbar')[1]).queryByRole('button', { name: 'Properties' })).not.toBeInTheDocument()\napp\\src\\components\\actions\\action_conversation_chat.test.tsx:212:    it('restores sticky behavior after the user returns within the end tolerance', () => {\napp\\src\\components\\actions\\action_conversation_chat.test.tsx:605:    it('keeps sticky position while reasoning and command output grow', () => {\napp\\src\\components\\actions\\action_editor_navigation.tsx:11:import { ActionPhraseToolbarControls } from './action_phrase_toolbar_controls'\napp\\src\\components\\actions\\action_editor_navigation.tsx:51:            toolbarContents: selectedPhrase ? phraseToolbarContents : undefined,\ndesign\\releases\\0_0_2\\B_019_project_open_form_placement.md:17:- Move open/create project into a dialog reachable from the toolbar (project menu button), combined with the F-027 repository/branch pickers.\ndesign\\releases\\0_0_2\\B_019_project_open_form_placement.md:18:- Branch switch and push become toolbar/menu commands shown only when a project is open (push only in manual mode, as today).\ndesign\\releases\\0_0_2\\B_019_project_open_form_placement.md:19:- New-card entry moves to a compact affordance in the card view (e.g. \"+ card\" per column or a single toolbar button opening a small dialog with title/type/body).\ndesign\\releases\\0_0_2\\B_019_project_open_form_placement.md:23:- With a project open, no setup fields are visible in the body; open/create/switch/push are reachable from the toolbar/menu.\napp\\src\\components\\actions\\action_editor.tsx:21:    toolbarContents?: () => ReactNode\napp\\src\\components\\text_view\\list_editor_toolbar_controls.tsx:15:import { MarkdownFormatToolbarControls } from '../editor/markdown_format_toolbar_controls'\napp\\src\\components\\text_view\\list_editor_toolbar_controls.test.tsx:11:import { ListEditorToolbarControls } from './list_editor_toolbar_controls'\napp\\src\\components\\text_view\\list_editor_toolbar_controls.test.tsx:13:vi.mock('../editor/markdown_format_toolbar_controls', () => ({MarkdownFormatToolbarControls: ({ endControls }: { endControls: ReactNode }) => <div>{endControls}</div>}))\napp\\src\\components\\text_view\\file_tree_view.tsx:16:import { FileTreeToolbar } from './file_tree_toolbar'\ndesign\\releases\\0_0_2\\B_013_text_view_body_only.md:14:F-007 specifies \"full-file editing for text view and body editing for card view\". `TextView` feeds `activeCard.content` (header already stripped by the parsing service) into `MarkdownEditor` and saves through `updateCardBody` — the frontmatter header is invisible and uneditable in file mode. Header mistakes (wrong status, typo'd id) can't be fixed anywhere in the app.\ndesign